sp_widget.client_script:
api.controller = function () {
    var c = this;

    c.refresh = function () {
        c.server.update().then(function (response) {
            c.data.royalties = response.data.royalties;
        });
    };

    c.getStatusClass = function (status) {
        var statusMap = {
            'collected': 'label-success',
            'pending': 'label-warning',
            'processing': 'label-info',
            'failed': 'label-danger',
            'disputed': 'label-danger'
        };
        return statusMap[status] || 'label-default';
    };

    c.formatCurrency = function (amount) {
        if (!amount) return '$0.00';
        return '$' + parseFloat(amount).toFixed(2).replace(/\d(?=(\d{3})+\.)/g, '$&,');
    };

    c.formatNumber = function (num) {
        if (!num) return '0';
        return parseInt(num).toLocaleString();
    };
};

sp_widget.css:
.royalty-list-container {
  padding: 20px 0;
}

.royalty-list-container .page-title {
  margin-top: 0;
  font-weight: 300;
  color: #333;
}

.royalty-list-container .table {
  margin-top: 15px;
}

.royalty-list-container .table th {
  background-color: #f5f5f5;
  font-weight: 600;
  text-transform: uppercase;
  font-size: 12px;
  letter-spacing: 0.5px;
  color: #555;
}

.royalty-list-container .table td {
  vertical-align: middle;
}

.royalty-list-container .label {
  font-size: 12px;
  padding: 4px 10px;
  border-radius: 3px;
  font-weight: 500;
}

sp_widget.script:
(function () {
    data.royalties = [];
    var gr = new GlideRecord('x_2015479_wa_str_0_royalty_col');
    gr.addActiveQuery();
    gr.orderByDesc('sys_created_on');
    gr.setLimit(100);
    gr.query();
    while (gr.next()) {
        data.royalties.push({
            sys_id: gr.getUniqueValue(),
            song: gr.getDisplayValue('song'),
            platform: gr.getValue('platform'),
            platform_display: gr.getDisplayValue('platform'),
            gross_amount: gr.getValue('gross_amount'),
            stream_count: gr.getValue('stream_count'),
            collection_status: gr.getValue('collection_status'),
            collection_status_display: gr.getDisplayValue('collection_status')
        });
    }
})();
